using System.Windows;using System.Windows.Controls;using FacialPresets;
namespace DanceStudio;
public sealed class StrengthCurvePanel:StackPanel {
 readonly Action begin,commit,cancel;readonly TextBox time=new(){Width=85},value=new(){Width=75};readonly ComboBox mode=new(){ItemsSource=new[]{"Linear","Hold"},SelectedIndex=0};readonly Border holder=new();StrengthCurveView? view;FacialSegment? segment;
 public StrengthCurvePanel(Action start,Action finish,Action abort){begin=start;commit=finish;cancel=abort;Children.Add(new TextBlock{Text=UiText.T("curveHint"),Foreground=StudioTheme.Muted,TextWrapping=TextWrapping.Wrap});var row=new WrapPanel();Children.Add(row);void B(string key,Action action){var b=new Button{Content=UiText.T(key)};b.Click+=(_,_)=>{try{action();}catch(Exception e){MessageBox.Show(UiText.Error(e.Message));}};row.Children.Add(b);}B("curveConvert",()=>{if(segment==null)return;begin();StrengthCurves.ConvertFade(segment);commit();});B("curveLegacy",()=>{if(segment==null)return;begin();segment.StrengthCurve=null;commit();});row.Children.Add(new TextBlock{Text=UiText.T("curveTime"),Foreground=StudioTheme.Text});row.Children.Add(time);row.Children.Add(new TextBlock{Text="%",Foreground=StudioTheme.Text});row.Children.Add(value);row.Children.Add(mode);B("curveApply",()=>view?.EditSelected(double.Parse(time.Text,System.Globalization.CultureInfo.InvariantCulture),double.Parse(value.Text,System.Globalization.CultureInfo.InvariantCulture)/100,mode.SelectedItem as string??"Linear"));B("curveDelete",()=>view?.DeleteSelected());Children.Add(holder);}
 bool amplification;public void SetAmplification(bool enabled){amplification=enabled;if(view!=null)view.AllowAmplification=enabled;}
 public void SelectPoint(Guid id)=>view?.SelectPoint(id);
 public void Bind(FacialSegment? c){if(ReferenceEquals(segment,c)){view?.Render();return;}segment=c;time.Text="";value.Text="";mode.SelectedIndex=0;IsEnabled=c!=null;holder.Child=null;if(c==null)return;view=new(c,true,begin,commit,cancel){AllowAmplification=amplification};view.PointSelected+=()=>{time.Text=view.SelectedPoint?.Time.ToString("0.######",System.Globalization.CultureInfo.InvariantCulture)??"";value.Text=(view.SelectedPoint?.Value*segment!.Gain*100)?.ToString("0.###",System.Globalization.CultureInfo.InvariantCulture)??"";mode.SelectedItem=view.SelectedPoint?.Interpolation??"Linear";};holder.Child=view;}
}
